27	export class ConsecaSafetyChecker implements InProcessChecker {
28	  private static instance: ConsecaSafetyChecker | undefined;
29	  private currentPolicy: SecurityPolicy | null = null;
30	  private activeUserPrompt: string | null = null;
31	  private config: Config | null = null;
32	
33	  /**
34	   * Private constructor to enforce singleton pattern.
35	   * Use `getInstance()` to access the instance.
36	   */
37	  private constructor() {}
38	
39	  static getInstance(): ConsecaSafetyChecker {
40	    if (!ConsecaSafetyChecker.instance) {
41	      ConsecaSafetyChecker.instance = new ConsecaSafetyChecker();
42	    }
43	    return ConsecaSafetyChecker.instance;
44	  }
45	
46	  /**
47	   * Resets the singleton instance. Use only in tests.
48	   */
49	  static resetInstance(): void {
50	    ConsecaSafetyChecker.instance = undefined;
51	  }
52	
53	  setConfig(config: Config): void {
54	    this.config = config;
55	  }
56	
57	  async check(input: SafetyCheckInput): Promise<SafetyCheckResult> {
58	    debugLogger.debug(
59	      `[Conseca] check called. History is: ${JSON.stringify(input.context.history)}`,
60	    );
61	
62	    if (!this.config) {
63	      debugLogger.debug('[Conseca] check failed: Config not initialized');
64	      return {
65	        decision: SafetyCheckDecision.ALLOW,
66	        reason: 'Config not initialized',
67	      };
68	    }
69	
70	    if (!this.config.enableConseca) {
71	      debugLogger.debug('[Conseca] check skipped: Conseca is not enabled.');
72	      return {
73	        decision: SafetyCheckDecision.ALLOW,
74	        reason: 'Conseca is disabled',
75	      };
76	    }
77	
78	    const userPrompt = this.extractUserPrompt(input);
79	    let trustedContent = '';
80	
81	    const toolRegistry = this.config.getToolRegistry();
82	    if (toolRegistry) {
83	      const tools = toolRegistry.getFunctionDeclarations();
84	      trustedContent = JSON.stringify(tools, null, 2);
85	    }
86	
87	    if (userPrompt) {
88	      await this.getPolicy(userPrompt, trustedContent, this.config);
89	    } else {
90	      debugLogger.debug(
91	        `[Conseca] Skipping policy generation because userPrompt is null`,
92	      );
93	    }
94	
95	    let result: SafetyCheckResult;
96	
97	    if (!this.currentPolicy) {
98	      result = {
99	        decision: SafetyCheckDecision.ALLOW, // Fallback if no policy generated yet
100	        reason: 'No security policy generated.',
101	        error: 'No security policy generated.',
102	      };
103	    } else {
104	      result = await enforcePolicy(
105	        this.currentPolicy,
106	        input.toolCall,
107	        this.config,
108	      );
109	    }
110	
111	    logConsecaVerdict(
112	      this.config,
113	      new ConsecaVerdictEvent(
114	        userPrompt || '',
115	        JSON.stringify(this.currentPolicy || {}),
116	        JSON.stringify(input.toolCall),
117	        result.decision,
118	        result.reason || '',
119	        'error' in result ? result.error : undefined,
120	      ),
121	    );
122	
123	    return result;
124	  }
125	
126	  async getPolicy(
127	    userPrompt: string,
128	    trustedContent: string,
129	    config: Config,
130	  ): Promise<SecurityPolicy> {
131	    if (this.activeUserPrompt === userPrompt && this.currentPolicy) {
132	      return this.currentPolicy;
133	    }
134	
135	    const { policy, error } = await generatePolicy(
136	      userPrompt,
137	      trustedContent,
138	      config,
139	    );
140	    this.currentPolicy = policy;
141	    this.activeUserPrompt = userPrompt;
142	
143	    logConsecaPolicyGeneration(
144	      config,
145	      new ConsecaPolicyGenerationEvent(
146	        userPrompt,
147	        trustedContent,
148	        JSON.stringify(policy),
149	        error,
150	      ),
151	    );
152	
153	    return policy;
154	  }
155	
156	  private extractUserPrompt(input: SafetyCheckInput): string | null {
157	    const prompt = input.context.history?.turns.at(-1)?.user.text;
158	    if (prompt) {
159	      return prompt;
160	    }
161	    debugLogger.debug(`[Conseca] extractUserPrompt failed.`);
162	    return null;
163	  }
164	
165	  // Helper methods for testing state
166	  getCurrentPolicy(): SecurityPolicy | null {
167	    return this.currentPolicy;
168	  }
169	
170	  getActiveUserPrompt(): string | null {
171	    return this.activeUserPrompt;
172	  }
173	}
